a.form_completion_time=b.form_completion_time
from capf2025_reference b
where a.reg_number=b."registrationNo" and a.self_checkin='Feedback';---50245


UPDATE capf_2025_tier1_admit_card
SET counter=sub.rn,
roll_number = region_code||'25'||'13'||sub.rn
FROM (
	
  SELECT reg_number, LPAD(ROW_NUMBER() OVER (partition by region ORDER BY form_completion_date,form_completion_time::time)::TEXT,7,'0') AS rn
  FROM capf_2025_tier1_admit_card where self_checkin='Yes'

) AS sub
WHERE capf_2025_tier1_admit_card.reg_number = sub.reg_number;-----

WITH max_per_region AS (
    SELECT 
        region,
        COALESCE(MAX(counter::int), 0) AS last_cnt
    FROM capf_2025_tier1_admit_card
    GROUP BY region
),
new_rows AS (
    SELECT 
        t.reg_number,
        t.region,
        m.last_cnt +
            ROW_NUMBER() OVER (
                PARTITION BY t.region 
                ORDER BY t.form_completion_date, t.form_completion_time::time
            ) AS new_cnt
    FROM capf_2025_tier1_admit_card t
    JOIN max_per_region m ON t.region = m.region
    WHERE t.counter IS NULL   --  only generate for NEW rows
)
UPDATE capf_2025_tier1_admit_card AS t
SET 
    counter = LPAD(new_rows.new_cnt::text, 7, '0'),
    roll_number = t.region_code || '25' || '13' || LPAD(new_rows.new_cnt::text, 7, '0')
FROM new_rows
WHERE t.reg_number = new_rows.reg_number;----50246

